#define _GNU_SOURCE
#include <sys/swap.h>
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <string.h>
#include <unistd.h>

// Define a custom high priority for the swap area
// Priority must be non-negative. 50 is an arbitrary high value.
#define CUSTOM_PRIORITY 50
#define SWAP_HIGH_PRIORITY_FLAGS \ 
    (SWAP_FLAG_PREFER | (CUSTOM_PRIORITY << SWAP_FLAG_PRIO_SHIFT))

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <path_to_prepared_swap_area>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *swap_path = argv[1];
    int ret;

    printf("Attempting to enable swap on %s with priority %d...\n", 
           swap_path, CUSTOM_PRIORITY);

    // swapon() call with high priority flags
    ret = swapon(swap_path, SWAP_HIGH_PRIORITY_FLAGS);

    if (ret == -1) {
        perror("swapon error");
        if (errno == EPERM) {
            fprintf(stderr, "\nError: swapon requires root privileges (CAP_SYS_ADMIN).\n");
        }
        return EXIT_FAILURE;
    }

    printf("Swap area successfully enabled.\n");

    // In a production environment, swapoff would be used to remove it.
    /*
    printf("\nAttempting to disable swap...\n");
    ret = swapoff(swap_path);
    if (ret == -1) {
        perror("swapoff error");
        return EXIT_FAILURE;
    }
    printf("Swap area successfully disabled.\n");
    */

    return EXIT_SUCCESS;
}
